#pragma once
// Forecasting with the CG bootstrap.
//
// The paper's conclusion notes that the same resampling scheme "can be
// further used for generating conditional future paths of yields ... to
// obtain measures of sampling uncertainty around projected paths".  That is
// what this module does, in two complementary ways:
//
//  A. Scenario simulation.  Starting from *today's* forward curve, future
//     curves are generated by drawing blocks of historical difference returns
//     (the "news") and re-running the curve identities.  The result is a
//     distribution of future yield curves and of bond holding-period returns.
//     The average simulated path differs from the forward curve by the
//     average historical term premium: forwards are not forecasts.
//
//  B. Predictive regression.  Excess returns are regressed on today's curve
//     shape (level, slope, curvature and, optionally, external predictors
//     such as trend inflation).  The CG bootstrap supplies p-values that are
//     valid despite persistent regressors and overlapping returns, and a
//     confidence interval for today's fitted expected return.
#include <cstdint>
#include <string>
#include <vector>

#include "mcb/stats/cg_bootstrap.hpp"

namespace mcb {

struct ForecastOptions {
  int horizon = 8;                 // periods to simulate
  int paths = 5000;
  std::vector<int> maturities;     // maturities (periods) to report
  std::uint64_t seed = 2024;
};

struct Distribution {
  double mean = 0, stdev = 0, q05 = 0, q16 = 0, q50 = 0, q84 = 0, q95 = 0;
};
Distribution summarize(const std::vector<double>& values);

struct YieldFan {
  int maturity = 0;                 // periods
  double current = 0.0;             // today's per-period yield
  std::vector<double> forwardImplied;  // yield at each future step if the forward curve were realised
  std::vector<Distribution> steps;  // distribution of the simulated yield at steps 1..horizon
};

struct ReturnForecast {
  int maturity = 0;       // periods
  int horizon = 0;        // holding period in periods
  double carryRollDown = 0.0;  // excess return if the curve does not move ("carry and roll-down")
  Distribution excessReturn;   // simulated log excess return over the holding period
  double probPositive = 0.0;   // share of paths with a positive excess return
  double breakEvenYieldRise = 0.0;  // rise in the (n-h)-period yield that wipes out the carry (per-period units)
};

struct ScenarioForecast {
  int horizon = 0, paths = 0;
  std::vector<YieldFan> fans;
  std::vector<ReturnForecast> returns;      // one per requested maturity (> horizon), holding = horizon
  std::vector<double> expectedShortRate;    // mean simulated one-period rate at steps 0..horizon
  std::vector<double> forwardShortRate;     // today's forward rate for the same future periods
};

/// Scenario simulation from the given current per-period yield curve (size N).
ScenarioForecast simulateScenarios(const CgBootstrap& cg, const Eigen::VectorXd& currentYields,
                                   const Eigen::VectorXd& currentExternal, const ForecastOptions& options);

/// Excess return over `horizon` periods of an n-period bond if the yield
/// curve is unchanged at the end of the holding period (per-period log units).
double carryAndRollDown(const Eigen::VectorXd& yields, int maturity, int horizon);

// ---- predictive regression ------------------------------------------------------

/// Level, slope and curvature of a curve as fixed combinations of yields:
/// level = y(N), slope = y(N) - y(1), curvature = 2 y(mid) - y(1) - y(N).
Eigen::Vector3d curveFactors(const Eigen::VectorXd& yields);
/// T x 3 matrix of curveFactors for every row.
Eigen::MatrixXd curveFactorMatrix(const Eigen::MatrixXd& yields);

struct PredictiveForecast {
  int maturity = 0, horizon = 0;
  std::vector<std::string> regressors;  // names, intercept first
  std::vector<double> beta, tStat, pBootstrap, pAsymptotic;
  double r2 = 0.0;
  int observations = 0;
  double fitted = 0.0;           // expected excess return given today's predictors
  double fittedStdErr = 0.0;     // bootstrap standard error of the fitted value
  double fittedLo68 = 0.0, fittedHi68 = 0.0, fittedLo90 = 0.0, fittedHi90 = 0.0;
  double unconditionalMean = 0.0;  // sample average excess return
};

/// Regresses rx(n,h)_{t+h} on the curve factors (and all external columns)
/// and evaluates the fit at the current state.  maturity = 0 uses the
/// cross-sectional average excess return over all maturities above the horizon.
PredictiveForecast predictiveForecast(const CgBootstrap& cg, int maturity, int horizon,
                                      const Eigen::VectorXd& currentYields, const Eigen::VectorXd& currentExternal,
                                      const std::vector<std::string>& externalNames, int replications,
                                      std::uint64_t seed);

}  // namespace mcb
